package com.aquaai.anomaly.domain.model;

import lombok.Getter;

import java.math.BigDecimal;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * Proposed anomaly detection candidate generated by a detector prior to
 * deduplication, cooldown, and persistence.
 */
@Getter
public class AnomalyCandidate {

    private final AnomalyType anomalyType;
    private final AnomalySeverity severity;
    private final BigDecimal detectedValue;
    private final BigDecimal expectedValue;
    private final BigDecimal deviation;
    private final BigDecimal confidence;
    private final String description;
    private final String explanation;
    private final String source;
    private final List<AnomalyEvidence> evidenceList;
    private final boolean isSimulated;

    public AnomalyCandidate(
            AnomalyType anomalyType,
            AnomalySeverity severity,
            BigDecimal detectedValue,
            BigDecimal expectedValue,
            BigDecimal deviation,
            BigDecimal confidence,
            String description,
            String explanation,
            String source,
            List<AnomalyEvidence> evidenceList,
            boolean isSimulated
    ) {
        this.anomalyType = Objects.requireNonNull(anomalyType, "anomalyType must not be null");
        this.severity = Objects.requireNonNull(severity, "severity must not be null");
        this.detectedValue = detectedValue;
        this.expectedValue = expectedValue;
        this.deviation = deviation;
        this.confidence = confidence != null ? confidence : BigDecimal.valueOf(0.80);
        this.description = Objects.requireNonNull(description, "description must not be null");
        this.explanation = Objects.requireNonNull(explanation, "explanation must not be null");
        this.source = source != null ? source : "RULE_ENGINE";
        this.evidenceList = evidenceList != null ? List.copyOf(evidenceList) : Collections.emptyList();
        this.isSimulated = isSimulated;
    }
}
